// Die Instanzwerte kommen aus sub-einstellungen (Knoten davor) und
// werden in der Data Table pw_config gepflegt (n8n-Oberfläche,
// "Data Tables"). HIER stehen nur die FACHLICHEN Werte dieses Workflows.
const werte = $('Einstellungen holen').first().json;
const pw = (key) => {
  const v = werte[key];
  if (v === undefined || String(v).trim() === '') {
    throw new Error('pw_config: "' + key + '" fehlt oder ist leer; in der n8n-Oberfläche unter "Data Tables" eintragen.');
  }
  return v;
};

// ══ KANALWAHL: steht in pw_config, nicht hier ═══════════════════
// Welcher Weg zum Steuerberater benutzt wird, entscheidet der
// Schlüssel "steuer_kanal" in der Data Table pw_config, umstellbar in
// der n8n-Oberfläche unter "Data Tables", ohne Deploy.
//
// WARUM NICHT FEST VERDRAHTET:
// Die Workflow-Dateien unter n8n/ teilen sich ALLE Instanzen. Steht der
// Kanal in der Datei, bekommt jede Instanz beim Einspielen denselben -
// eine Installation fährt aber DUO, eine andere sevDesk. Instanz-
// spezifisches gehört in pw_config, und genau dafür gibt es sie.
//
// Ein Kanal ist ein Adresspaar plus ein Versand-Sub. sevDesk hat einen
// EIGENEN Absender: die Autobox verwirft Mail von nicht hinterlegten
// Adressen stillschweigend.
const kanaele = {
  duo:     { name: 'DUO',     empf: 'mail_duo',     abs: 'mail_absender',         sub: 'pwSubDuoVersand' },
  // DUO mit paper-werk: bei XRechnung geht das XML als zweiter
  // Anhang mit. Nur mit paper-werk, siehe sub-duo-versand-paperwerk.
  duo_paperwerk: { name: 'DUO', empf: 'mail_duo', abs: 'mail_absender', sub: 'pwSubDuoVersPW1' },
  stb:     { name: 'StB',     empf: 'mail_stb',     abs: 'mail_absender',         sub: 'pwSubStbVersand' },
  sevdesk: { name: 'sevDesk', empf: 'mail_sevdesk', abs: 'mail_sevdesk_absender', sub: 'pwSubSevdeskVer' }
};
const gewaehlt = String(pw('steuer_kanal')).trim().toLowerCase();
const kanal = kanaele[gewaehlt];
if (!kanal) {
  throw new Error('pw_config: "steuer_kanal" steht auf "' + gewaehlt + '"; erlaubt sind: ' + Object.keys(kanaele).join(', ') + '.');
}
// ════════════════════════════════════════════════════════════════

return [{
  json: {
    // ── aus pw_config ──
    paperless_url: pw('paperless_url'),
    kanal: kanal.name,
    empfaenger: pw(kanal.empf),
    absender: pw(kanal.abs),
    // Welchen Sub der Knoten "Versand ausführen" ruft, als Ausdruck,
    // damit die Kanalwahl an EINER Stelle bleibt.
    versand_sub: kanal.sub,

    // ── fachlich, hier zu pflegen ──
    // tag_kommando: setzt ein Mensch und meint "an den Steuerberater".
    //   Bewusst kanalneutral benannt: Welcher Weg das ist, geht ihn
    //   nichts an.
    // tag_gesendet: ERGEBNIS, bleibt dauerhaft dran und verhindert den
    //   zweiten Versand für immer. Anders als bei Titel und OCR ist
    //   Wiederholen hier NICHT erwünscht.
    // tag_pending:  global, nicht workflow-spezifisch. Solange er hängt,
    //   ruht JEDE Verarbeitung dieses Dokuments.
    tag_kommando: 'Steuer-senden',
    tag_gesendet: 'Steuer-gesendet',
    tag_pending: 'wird bearbeitet',

    // dateiname_quelle: 'titel' = Paperless-Titel als Anhangsname
    //   (sprechend), 'original' = Original-Dateiname (oft Scanner-Namen
    //   wie Scan_00382.pdf).
    dateiname_quelle: 'titel'
  }
}];

// Dokument-ID aus dem Paperless-Aufruf holen.
//
// WIRFT BEWUSST NICHT, wenn keine dabei ist: Ein Auslöser vom Typ
// "Consumption" ruft ohne doc_url auf, weil das Dokument zu dem
// Zeitpunkt noch gar nicht existiert; Paperless setzt den Platzhalter
// dann auf einen leeren String. Ein Kunde darf so einen Auslöser
// anlegen, ohne dass Fehlermails entstehen. Der Workflow endet dann ohne Meldung.
const body = $('Webhook').first().json.body ?? {};
let id = body.doc_id ?? body.id;
if (!id && body.doc_url) {
  id = String(body.doc_url).match(/\/documents\/(\d+)/)?.[1];
}

return [{
  json: Object.assign({}, $('Konfiguration').first().json, {
    doc_id: id ? Number(id) : null,
    grund: id ? null : 'Aufruf ohne Dokument-ID, vermutlich ein Auslöser, der schon beim Einzug feuert. Nichts zu tun.'
  })
}];

// Wächter: Was ist hier eigentlich zu tun?
//
// Alle Prüfungen schauen auf den ECHTEN Dokumentzustand, nicht auf
// eine Absprache mit Paperless. Damit kann eine geänderte
// Auslöser-Konfiguration nichts kaputtmachen; sie erzeugt
// höchstens Leerläufe.
const cfg = $('Konfiguration').first().json;
const doc_id = $('Auftrag lesen').first().json.doc_id;
const alleTags = $('Tags laden').first().json.results || [];
const doc = $input.first().json;

const finde = (name) => alleTags.find(t => String(t.name).toLowerCase() === String(name).toLowerCase());
const kommando = finde(cfg.tag_kommando);
const gesendet = finde(cfg.tag_gesendet);
const pending  = finde(cfg.tag_pending);

// Fehlende Tags sind ein echter Einrichtungsfehler und keine
// Zuständigkeitsfrage; hier wird geworfen.
if (!kommando) throw new Error('Tag "' + cfg.tag_kommando + '" existiert nicht in Paperless; bitte anlegen.');
if (!gesendet) throw new Error('Tag "' + cfg.tag_gesendet + '" existiert nicht in Paperless; bitte anlegen.');
if (!pending)  throw new Error('Tag "' + cfg.tag_pending + '" existiert nicht in Paperless; bitte anlegen (das globale "wird bearbeitet").');

const hat = (t) => (doc.tags || []).includes(t.id);

// Drei Ausgänge. 'buchungsrelevant' steht hier absichtlich nicht:
// ein Mensch hat das Dokument ausdrücklich zum Senden markiert, das
// IST die Entscheidung. Beim Monatslauf ist es umgekehrt: Dort ist
// 'buchungsrelevant' das Auswahlkriterium.
let aktion, grund;
if (!hat(kommando)) {
  aktion = 'nichts';
  grund = 'Dokument trägt "' + cfg.tag_kommando + '" nicht; der Aufruf kam von einem anderen Auslöser. Nichts zu tun.';
} else if (hat(pending)) {
  aktion = 'nichts';
  grund = 'Dokument ist als "' + cfg.tag_pending + '" markiert; es läuft bereits eine Verarbeitung. Nichts zu tun.';
} else if (hat(gesendet)) {
  aktion = 'quittieren';
  grund = 'Dokument trägt bereits "' + cfg.tag_gesendet + '"; es wurde schon einmal an den Steuerberater übermittelt und geht nicht erneut raus. Das Kommando-Tag wird trotzdem entfernt. Für einen bewussten Zweitversand zuerst "' + cfg.tag_gesendet + '" von Hand entfernen.';
} else {
  aktion = 'senden';
  grund = null;
}

return [{
  json: Object.assign({}, cfg, {
    doc_id,
    titel: doc.title || ('Dokument ' + doc_id),
    tag_kommando_id: kommando.id,
    tag_gesendet_id: gesendet.id,
    tag_pending_id: pending.id,
    aktion,
    grund
  })
}];

// Kommando- und pending-Tag sind in EINEM Aufruf weggeräumt, das
// Ergebnis-Tag "Steuer-gesendet" hat der Versand-Sub gesetzt. Der
// Zustand danach trägt weder Kommando noch pending; der
// Paperless-Auslöser greift also nicht erneut, und der Lauf ist zu
// Ende.
const lage = $('Lage prüfen').first().json;
const versand = $('Versand ausführen').first().json;
return [{ json: {
  status: 'gesendet',
  kanal: versand.kanal ?? lage.kanal,
  doc_id: lage.doc_id,
  titel: lage.titel
} }];

// Auftrag erledigt, aber nichts verschickt. Kein pending-Tag nötig:
// entfernt wird nur das Kommando-Tag, und der Zustand danach trägt
// es nicht mehr; der Auslöser greift also nicht erneut.
const lage = $('Lage prüfen').first().json;
return [{ json: {
  status: 'nicht gesendet',
  doc_id: lage.doc_id,
  titel: lage.titel,
  grund: lage.grund
} }];

// Ende ohne Meldung: kein Fehler, keine Mail. Der Aufruf war schlicht
// nicht für uns. Er taucht in der n8n-Liste als erfolgreicher Lauf
// auf, und der Grund steht im Ergebnis; damit ist nachvollziehbar,
// WARUM nichts passiert ist, ohne dass jemand aufgeschreckt wird.
return [{ json: {
  status: 'übersprungen',
  grund: $json.grund ?? 'unbekannt',
  doc_id: $json.doc_id ?? null
} }];
